import Mathlib

def StepCost (t d v : ℕ) : ℝ := 12 * (d : ℝ)^2 + 4 * (t : ℝ) * d + 8 * t + 7 * d + (d : ℝ) * v + v - 3

def Claim : Prop := ∀ v : ℕ, 1 ≤ v → ∃ c C : ℝ, 0 < c ∧ 0 < C ∧ ∀ t d : ℕ, 1 ≤ t → 1 ≤ d → c * ((t : ℝ) * d + (d : ℝ)^2) ≤ StepCost t d v ∧ StepCost t d v ≤ C * ((t : ℝ) * d + (d : ℝ)^2)

import Mathlib

def StoreWords (n d : ℕ) : ℝ := 4 * (n : ℝ) * d + d + 1

def Claim : Prop := ∃ c C : ℝ, 0 < c ∧ 0 < C ∧ ∀ n d : ℕ, 1 ≤ n → 1 ≤ d → c * ((n : ℝ) * d) ≤ StoreWords n d ∧ StoreWords n d ≤ C * ((n : ℝ) * d)

import Mathlib

def SequenceCost (n d v : ℕ) : ℝ := 2 * (d : ℝ) * n * ((n : ℝ) + 1) + 4 * (n : ℝ) * ((n : ℝ) + 1) + (n : ℝ) * (12 * (d : ℝ)^2 + 7 * d + (d : ℝ) * v + v - 3)

def Claim : Prop := ∀ v : ℕ, 1 ≤ v → ∃ c C : ℝ, 0 < c ∧ 0 < C ∧ ∀ n d : ℕ, 1 ≤ n → 1 ≤ d → c * ((n : ℝ)^2 * d + (n : ℝ) * (d : ℝ)^2) ≤ SequenceCost n d v ∧ SequenceCost n d v ≤ C * ((n : ℝ)^2 * d + (n : ℝ) * (d : ℝ)^2)
